/bin/bash -lc "node --input-type=module <<'EOF'
import { spawn } from 'node:child_process';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { once } from 'node:events';
await mkdir('data', { recursive: true });
const directory = await mkdtemp(join(process.cwd(), 'data', 'launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(new Error('Startup timed out')), 5000);
    child.stdout.on('data', chunk => {
      if (chunk.toString().includes('listening on port 18080')) { clearTimeout(timeout); resolve(); }
    });
    child.once('error', reject);
  });
  const response = await fetch('http://127.0.0.1:18080/health');
  if (response.status "'!== 200 || JSON.stringify(await response.json()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start launch contract and /health verified');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
EOF
"

